//! Automatic composition of short tunes.
//!
//! This crate is a port of the TypeScript implementation. Up to commit 83edec0 it reproduced the
//! TypeScript behaviour exactly, including the order in which random numbers are consumed and the
//! known bugs. Since then the bugs have been fixed, and the golden fixtures (`fixtures/golden/`)
//! are generated by this crate (`cargo run --example gen_golden`).
//!
//! The TypeScript implementation was removed from the repository after commit ece5a07.
//! The comments that name its files (`src/core/*.ts`) refer to that history.

pub mod error;
pub mod generator;
pub mod linalg;
pub mod markov;
pub mod random;
pub mod snapshot;
pub mod tune;
pub mod util;
